import {escapeHTML as e, safeImage, migrateForm, TYPES, FILE_TYPES, closedReason, displayAnswer, validateDefinition, memberName} from '/shared/forms-core.js';
import {icon, wordmark, emptyState} from '/shared/ui.js';
import {memberCard,presidentCard,TeamMemberCard} from '/shared/team-view.js';
import {cropPortrait,cropPoster} from './cropper.js';
import {uploadImage,waitForUploads,dataURLFile} from './media-upload.js';
import {CELLS} from '/shared/activities-view.js';
import {ActivityArticle} from '/shared/activity-article.js';

let site,stats,drafts=[],page='dashboard',draft=null,dirty=false,autosaveTimer,saving=Promise.resolve(),editorGeneration=0;
const app=document.querySelector('#app'),uid=()=>crypto.randomUUID();
const labels={dashboard:['chart','Tableau de bord'],forms:['form','Formulaires'],announcements:['calendar','Annonces'],activities:['sport','Activités passées'],members:['people','Bureau'],identity:['image','Identité']};
let noticeTimer;
function notice(message,error=false){const n=document.querySelector('#notice');n.textContent=message;n.classList.toggle('error',error);n.hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.hidden=true,6000);}
async function api(route,method='GET',data){
 const response=await fetch('/api/'+route,{method,headers:{'Content-Type':'application/json'},...(data!==undefined?{body:JSON.stringify(data)}:{})});
 const result=await response.json();if(!response.ok){const err=new Error(result.error||'Une erreur est survenue.');err.status=response.status;throw err;}return result;
}
function wireActions(root=app){root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>dispatch(b.dataset.action,b.dataset.id));}
function action(name,label,kind='secondary',id=''){return `<button type="button" class="button ${kind}" data-action="${name}" data-id="${e(id)}">${icon(name==='newForm'||name==='newContent'?'plus':name==='preview'?'eye':name==='saveForm'?'check':'arrow')}${e(label)}</button>`;}
function heading(title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">L’ATELIER DU BUREAU</div><h1>${e(title)}</h1><p>${e(description)}</p></div><div class="actions">${actions}</div></div>`;}
function field(label,key,value='',type='text',extra=''){return `<label class="field"><span>${e(label)}</span>${type==='textarea'?`<textarea data-key="${e(key)}" ${extra}>${e(value)}</textarea>`:`<input type="${type}" data-key="${e(key)}" value="${e(value)}" ${extra}>`}</label>`;}
function selectField(label,key,value,items){return `<label class="field"><span>${e(label)}</span><select data-key="${e(key)}">${items.map(([id,name])=>`<option value="${e(id)}" ${String(value)===String(id)?'selected':''}>${e(name)}</option>`).join('')}</select></label>`;}
function toggle(label,key,value){return `<label class="toggle"><input type="checkbox" data-key="${e(key)}" ${value?'checked':''}>${e(label)}</label>`;}
function upload(label,key,source,kind=''){return `<div class="upload-box" data-upload-box="${e(key)}"><span>${e(label)}</span><p class="hint">PNG, JPEG ou WebP · 10 Mo maximum. ${kind==='a4'?'Cadrage A4 obligatoire avant import.':'L’image reste entière.'}</p><input type="file" accept="image/png,image/jpeg,image/webp" data-upload="${e(key)}" ${kind==='a4'?'data-poster="a4"':''} aria-label="${e(label)}">${safeImage(source)?`<img class="upload-preview" src="${e(source)}" alt="Aperçu de ${e(label)}">`:''}<button class="button secondary" type="button" data-clear="${e(key)}">Retirer l’image</button></div>`;}
function bind(root,obj,onChange=()=>{dirty=true;}){
 root.querySelectorAll('[data-key]').forEach(n=>n.addEventListener('input',()=>{obj[n.dataset.key]=n.type==='checkbox'?n.checked:['number','range'].includes(n.type)?(n.value===''?'':Number(n.value)):n.value;onChange(n.dataset.key);}));
 root.querySelectorAll('[data-upload]').forEach(n=>n.onchange=async()=>{
  const file=n.files[0];if(!file)return;
  n.disabled=true;dirty=true;
  try{let selected=file;if(n.dataset.poster==='a4'){const result=await cropPoster(file);if(!result)return;selected=dataURLFile(result,'affiche-a4.webp');obj.posterFormat='A4';}const source=await uploadImage(selected);obj[n.dataset.upload]=source;const box=n.closest('.upload-box');let img=box.querySelector('img');if(!img){img=document.createElement('img');img.className='upload-preview';img.alt='Aperçu de l’image';box.append(img);}img.src=source;onChange(n.dataset.upload);notice('Image transférée. Enregistrez pour la publier.');}catch(err){notice(err.message,true);}finally{n.disabled=false;}

 });
 root.querySelectorAll('[data-clear]').forEach(n=>n.onclick=()=>{obj[n.dataset.clear]='';n.closest('.upload-box').querySelector('img')?.remove();n.closest('.upload-box').querySelector('input').value='';onChange(n.dataset.clear);});
}
async function saveSite(next=site){await waitForUploads();const result=await api('site','PUT',next);next.revision=result.revision;next.activityRevision=result.activityRevision;next.teamRevision=result.teamRevision;site=next;dirty=false;document.querySelector('#admin-brand').innerHTML=wordmark(site,'fr',true);}
async function refresh(){[stats,site,drafts]=await Promise.all([api('stats'),api('site'),api('drafts')]);}
function canLeave(){return !dirty||confirm('Des modifications ne sont pas encore enregistrées. Quitter cette page ?');}
async function navigate(next){if(!canLeave())return;clearTimeout(autosaveTimer);editorGeneration++;dirty=false;draft=null;page=next;render();}
function render(){document.querySelector('#admin-brand').innerHTML=wordmark(site||{},'fr',true);document.querySelector('#breadcrumb').textContent=labels[page][1];document.querySelectorAll('[data-page]').forEach(n=>n.classList.toggle('active',n.dataset.page===page));if(page==='dashboard')dashboard();else if(page==='forms')forms();else if(page==='identity')identity();else if(page==='activities')activityList();else content();}
function login(){site=null;document.querySelector('#admin-brand').innerHTML=wordmark({logo:'/assets/logo-club.png'},'fr',true);app.innerHTML=`<div class="panel login-panel"><div class="login-icon">${icon('lock')}</div><div class="eyebrow" style="margin-block-start:25px">INFINITY SPACE · FSBM</div><h1>Les idées prennent<br>vie ici.</h1><p>Bienvenue dans l’atelier du bureau.<br>Connectez-vous pour faire avancer le collectif.</p><form id="login">${field('Mot de passe','password','','password','autocomplete="current-password" required')}<button class="button" type="submit">Ouvrir l’atelier ${icon('arrow')}</button><p class="login-error" id="login-error" role="alert"></p></form></div>`;app.querySelector('#login').onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('button');button.disabled=true;try{await api('login','POST',{password:ev.target.querySelector('input').value});await refresh();render();}catch(err){app.querySelector('#login-error').textContent=err.message;}finally{button.disabled=false;}};}
function dashboard(){
 const days=Array.from({length:7},(_,i)=>{const day=new Date(Date.now()-(6-i)*86400000).toISOString().slice(0,10);return {day,count:stats.visits.find(v=>v.day===day)?.count||0};});const max=Math.max(1,...days.map(d=>d.count));const week=days[0].day;const weekResponses=stats.responses.filter(r=>r.created.slice(0,10)>=week).length;
 const chart=`<svg class="weekly-chart" viewBox="0 0 560 190" role="img" aria-label="Pages vues par jour : ${days.map(d=>d.day+' : '+d.count).join(', ')}"><path d="M8 150H552M8 80H552M8 10H552" stroke="var(--line)" stroke-dasharray="3 5"/>${days.map((d,i)=>{const x=25+i*77,h=d.count/max*110;return `<rect class="chart-bar" x="${x}" y="${150-Math.max(h,2)}" width="32" height="${Math.max(h,2)}" rx="3"/><text x="${x+16}" y="${140-Math.max(h,2)}" text-anchor="middle">${d.count}</text><text x="${x+16}" y="176" text-anchor="middle">${new Date(d.day+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'short'})}</text>`;}).join('')}</svg>`;
 app.innerHTML=heading('Bonjour, le bureau.','Un regard sur la communauté, et de nouvelles idées à faire vivre.',action('newForm','Créer un formulaire','accent'))+`<div class="stats-grid">${[['Pages vues',days.reduce((a,b)=>a+b.count,0),'7 jours · UTC','eye'],['Réponses reçues',weekResponses,'7 jours · UTC','form'],['Formulaires publiés',site.forms.filter(f=>f.published).length,'Sur le site du club','chart']].map(([title,note,sub,i])=>`<div class="panel stat-card"><span>${title}</span>${icon(i)}<strong>${note}</strong><small>${sub}</small></div>`).join('')}</div><div class="dashboard-grid"><section class="panel"><h2>La semaine en mouvement</h2><p>Les visites du site, jour après jour.</p>${chart}<p class="chart-caption">Les pages vues comptent les chargements, pas les visiteurs uniques.</p></section><section class="panel"><h2>Les dernières réponses</h2>${stats.responses.slice(0,4).map(r=>`<div class="recent-item">${icon('form')}<div><strong>${e(r.snapshot.title||site.forms.find(f=>f.id===r.form)?.title||'Formulaire archivé')}</strong><small>${e(new Date(r.created).toLocaleString('fr-FR'))}</small><button class="text-link" data-action="responses" data-id="${e(r.form)}">Consulter ${icon('arrow')}</button></div></div>`).join('')||'<p class="hint">Les premières réponses apparaîtront ici. Votre prochain formulaire n’attend que vous.</p>'}</section></div><section class="panel"><h2>La suite commence avec une idée.</h2><p>Une annonce pour réunir le collectif, un formulaire pour passer à l’action.</p><div class="actions" style="margin-block-start:20px">${action('newForm','Nouveau formulaire')}${action('newContent','Nouvelle annonce','','announcements')}</div></section><section class="panel"><h2>Les inscriptions, en chiffres</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Formulaire</th><th>Ouvertures · total</th><th>Réponses · total</th><th>Statut</th></tr></thead><tbody>${site.forms.map(f=>`<tr><td>${e(f.title)}</td><td>${stats.formVisits.find(v=>v.page==='/forms/'+f.id)?.count||0}</td><td>${count(f.id)}</td><td>${statusBadge(f)}</td></tr>`).join('')}</tbody></table></div>${site.forms.length?'':emptyState('À chaque activité, son formulaire.','Créez votre première inscription pour suivre sa participation.','form')}</section>`;wireActions();
}
const count=id=>stats.responses.filter(r=>r.form===id).length;
function statusBadge(f){const status=!f.published?'draft':closedReason(f,count(f.id))?'closed':'published';return `<span class="badge ${status}">${{draft:'Brouillon',closed:'Fermé',published:'Publié'}[status]}</span>`;}
function allForms(){const map=new Map(site.forms.map(f=>[f.id,f]));for(const d of drafts)if(!map.has(d.id))map.set(d.id,d.value);return [...map.values()];}
function forms(){
 app.innerHTML=heading('Les formulaires.','Du premier rendez-vous à la dernière réponse.',action('newForm','Créer un formulaire','accent')+(stats.responses.some(r=>!site.forms.some(f=>f.id===r.form))?action('responses','Réponses archivées','secondary',stats.responses.find(r=>!site.forms.some(f=>f.id===r.form)).form):''))+`<div class="panel"><div class="toolbar"><label class="search-box">${icon('search')}<input id="form-search" aria-label="Rechercher un formulaire" placeholder="Rechercher un formulaire…"></label><label class="field" style="margin:0"><span class="hint">Trier par</span><select id="form-sort"><option value="title">Titre A–Z</option><option value="responses">Nombre de réponses</option></select></label></div><div id="form-table"></div></div>`;
 function table(){let items=allForms().filter(f=>(f.title||'Sans titre').toLocaleLowerCase().includes(app.querySelector('#form-search').value.toLocaleLowerCase()));items.sort(app.querySelector('#form-sort').value==='responses'?(a,b)=>count(b.id)-count(a.id):(a,b)=>(a.title||'').localeCompare(b.title||'','fr'));
  app.querySelector('#form-table').innerHTML=items.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Titre</th><th>Statut</th><th>Réponses</th><th>Actions</th></tr></thead><tbody>${items.map(f=>`<tr><td class="title-cell"><strong>${e(f.title||'Sans titre')}</strong>${drafts.some(d=>d.id===f.id)?'<p class="hint">Modifications en brouillon</p>':''}</td><td>${statusBadge(f)}</td><td>${count(f.id)}</td><td><div class="actions"><button class="icon-button" data-action="editForm" data-id="${e(f.id)}" aria-label="Modifier ${e(f.title)}">${icon('edit')}</button><button class="icon-button" data-action="responses" data-id="${e(f.id)}" aria-label="Réponses de ${e(f.title)}">${icon('chart')}</button><button class="icon-button" data-action="duplicateForm" data-id="${e(f.id)}" aria-label="Dupliquer ${e(f.title)}">${icon('copy')}</button><button class="icon-button danger" data-action="deleteForm" data-id="${e(f.id)}" aria-label="Supprimer ${e(f.title)}">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:emptyState('La prochaine activité commence ici.','Aucun formulaire trouvé. Créez-en un pour accueillir vos participants.','form');wireActions();
 }app.querySelector('#form-search').oninput=table;app.querySelector('#form-sort').onchange=table;table();wireActions();
}
function newQuestion(section){return {id:uid(),section,type:'short',label:'',labelAr:'',description:'',descriptionAr:'',required:false,options:[{id:uid(),label:'Option 1',labelAr:''}],rows:[{id:uid(),label:'Ligne 1',labelAr:''}],columns:[{id:uid(),label:'Colonne 1',labelAr:''}],validation:{},min:1,max:5,allowedTypes:['application/pdf','image/png','image/jpeg'],maxBytes:2*1024*1024};}
async function startForm(id){
 clearTimeout(autosaveTimer);editorGeneration++;page='forms';dirty=false;
 if(id){const auto=drafts.find(d=>d.id===id);draft=migrateForm(auto?.value||site.forms.find(f=>f.id===id));}
 else{const sid=uid();draft=migrateForm({id:uid(),title:'',titleAr:'',description:'',descriptionAr:'',published:false,sections:[{id:sid,title:'',description:''}],questions:[newQuestion(sid)],confirmation:'',confirmationAr:'',submitAnother:false});}
 editor();
}
function changed(){dirty=true;const indicator=app.querySelector('#save-indicator');if(indicator)indicator.textContent='Modifications en cours…';clearTimeout(autosaveTimer);autosaveTimer=setTimeout(()=>flushDraft().catch(err=>notice(err.message,true)),850);}
async function flushDraft(){
 clearTimeout(autosaveTimer);if(!draft)return;const snapshot=structuredClone(draft),generation=editorGeneration;
 saving=saving.catch(()=>{}).then(async()=>{await api('drafts/'+snapshot.id,'PUT',snapshot);const record={id:snapshot.id,value:snapshot,updated:new Date().toISOString()};drafts=drafts.filter(d=>d.id!==snapshot.id);drafts.push(record);
  if(generation===editorGeneration&&JSON.stringify(draft)===JSON.stringify(snapshot)){dirty=false;const n=app.querySelector('#save-indicator');if(n)n.textContent='Brouillon enregistré · '+new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});}
 });return saving;
}
function bilingual(first,second,obj,key,type='text',extra=''){return `<div class="two-columns"><div>${field(first,key,obj[key],type,extra)}</div><div dir="rtl">${field(second,key+'Ar',obj[key+'Ar'],type,extra)}</div></div>`;}
function optionRows(q,key,title){return `<div data-option-list="${key}"><p class="list-label">${e(title)} · Français / العربية</p>${q[key].map((o,i)=>`<div class="option-editor" data-option="${key}:${i}"><input data-option-key="label" aria-label="${e(title)} ${i+1} français" value="${e(o.label)}"><input data-option-key="labelAr" dir="rtl" aria-label="${e(title)} ${i+1} arabe" value="${e(o.labelAr)}"><button type="button" class="icon-button danger" data-qaction="removeOption" data-list="${key}" data-index="${i}" aria-label="Supprimer cette option">${icon('close')}</button></div>`).join('')}<button type="button" class="text-link" data-qaction="addOption" data-list="${key}">${icon('plus')}Ajouter ${key==='rows'?'une ligne':key==='columns'?'une colonne':'une option'}</button></div>`;}
function questionEditor(q,index){
 const typeOptions=Object.entries(TYPES).map(([id,title])=>`<option value="${id}" ${q.type===id?'selected':''}>${title}</option>`).join('');
 let settings='';
 if(['choice','checkboxes','dropdown'].includes(q.type))settings=optionRows(q,'options','Option')+(q.type!=='dropdown'?toggle('Ajouter une réponse « Autre »','other',q.other):'')+toggle('Mélanger les options','shuffle',q.shuffle);
 if(q.type==='scale')settings=`<div class="two-columns">${selectField('Échelle','max',q.max,[[5,'De 1 à 5'],[10,'De 1 à 10']])}<div></div></div>${bilingual('Libellé minimum','وصف الحد الأدنى',q,'minLabel')}${bilingual('Libellé maximum','وصف الحد الأقصى',q,'maxLabel')}`;
 if(['grid','checkboxGrid'].includes(q.type))settings=optionRows(q,'rows','Ligne')+optionRows(q,'columns','Colonne');
 if(q.type==='file')settings=`<div class="field"><span>Formats autorisés</span>${FILE_TYPES.map(type=>`<label class="toggle"><input type="checkbox" data-filetype="${type}" ${q.allowedTypes.includes(type)?'checked':''}>${type}</label>`).join('')}</div>${selectField('Taille maximale','maxBytes',q.maxBytes,[[262144,'256 Ko'],[1048576,'1 Mo'],[2097152,'2 Mo']])}<p class="hint">Fichiers privés, accessibles seulement dans les réponses du bureau.</p>`;
 const validation=['short','long'].includes(q.type)?`<details><summary>Validation de la réponse</summary><div class="validation-fields">${selectField('Format','preset',q.validation.preset||'',[['','Texte libre'],['email','E-mail'],['phone','Téléphone'],['number','Nombre']])}<div class="two-columns">${field('Longueur minimum','minLength',q.validation.minLength,'number','min="0" max="10000"')}${field('Longueur maximum','maxLength',q.validation.maxLength,'number','min="1" max="10000"')}</div><div class="two-columns">${field('Valeur minimum · nombres','min',q.validation.min,'number')}${field('Valeur maximum · nombres','max',q.validation.max,'number')}</div>${field('Expression régulière · format avancé','regex',q.validation.regex)}<p class="hint">Expressions simples : sans groupes ni alternatives, une seule répétition variable. Réponses limitées à 1 000 caractères.</p></div></details>`:'';
 const routes=['choice','dropdown'].includes(q.type)?`<details><summary>Aller à une section selon la réponse</summary>${q.options.map(o=>`<label class="field"><span>${e(o.label)}</span><select data-route="${e(o.id)}"><option value="">Section suivante</option>${draft.sections.filter(s=>draft.sections.indexOf(s)>draft.sections.findIndex(s=>s.id===q.section)).map((s,i)=>`<option value="${e(s.id)}" ${q.routes?.[o.id]===s.id?'selected':''}>${e(s.title||'Section '+(draft.sections.indexOf(s)+1))}</option>`).join('')}<option value="submit" ${q.routes?.[o.id]==='submit'?'selected':''}>Envoyer le formulaire</option></select></label>`).join('')}<p class="hint">Si plusieurs questions ont une branche, la première réponse avec une branche détermine la suite.</p></details>`:'';
 return `<article class="panel question-card" data-question="${q.id}"><div class="question-toolbar"><span class="question-number">QUESTION ${String(index+1).padStart(2,'0')}</span><select data-type aria-label="Type de la question ${index+1}">${typeOptions}</select></div>${bilingual('Question · Français','السؤال · العربية',q,'label','text','class="inline-field question-title" placeholder="Votre question"')}${bilingual('Aide · Français','نص المساعدة · العربية',q,'description')}${settings}${validation}${routes}<div class="question-footer">${toggle('Obligatoire','required',q.required)}<div class="actions"><button type="button" class="icon-button" data-qaction="up" aria-label="Monter la question">${icon('up')}</button><button type="button" class="icon-button" data-qaction="down" aria-label="Descendre la question">${icon('down')}</button><button type="button" class="icon-button" data-qaction="duplicate" aria-label="Dupliquer la question">${icon('copy')}</button><button type="button" class="icon-button danger" data-qaction="delete" aria-label="Supprimer la question">${icon('trash')}</button></div></div>${draft.sections.length>1?selectField('Déplacer vers la section','section',q.section,draft.sections.map((s,i)=>[s.id,s.title||'Section '+(i+1)])):''}</article>`;
}
function localDate(iso){if(!iso)return '';const d=new Date(iso);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function editor(){
 document.querySelector('#breadcrumb').textContent='Créateur de formulaires';
 app.innerHTML=heading('Une idée, un formulaire.','Écrivez directement dans le formulaire. Le brouillon est enregistré automatiquement.',action('preview','Aperçu')+action('saveForm',draft.published?'Mettre à jour le site':'Enregistrer / publier','accent'))+`<div class="editor-layout"><div class="builder-canvas"><section class="panel builder-cover" id="form-fields"><div class="eyebrow">INFINITY SPACE · FSBM</div>${bilingual('Titre du formulaire · Français','عنوان الاستمارة · العربية',draft,'title','text','class="inline-field editor-title" placeholder="Une nouvelle aventure…"')}${bilingual('Description · Français','الوصف · العربية',draft,'description','textarea')}${upload('Image d’en-tête','image',draft.image)}</section><div id="section-list">${draft.sections.map((s,si)=>`<section data-section="${e(s.id)}"><div class="panel section-card"><div class="question-toolbar"><span class="question-number">SECTION ${si+1}</span>${si>0?`<button type="button" class="icon-button danger" data-section-delete="${s.id}" aria-label="Supprimer la section">${icon('trash')}</button>`:''}</div><div class="section-fields">${bilingual('Titre de section','عنوان القسم',s,'title')}${bilingual('Description de section','وصف القسم',s,'description')}</div></div>${draft.questions.filter(q=>q.section===s.id).map(q=>questionEditor(q,draft.questions.indexOf(q))).join('')}<button type="button" class="button secondary add-question" data-add-question="${s.id}">${icon('plus')}Ajouter une question</button></section>`).join('')}</div><button type="button" class="button secondary" id="add-section">${icon('plus')}Ajouter une section</button></div><aside class="panel builder-settings"><h2>Les détails font la différence.</h2><div id="form-settings">${toggle('Publié sur le site','published',draft.published)}${toggle('Accepter les réponses','accepting',draft.accepting)}${field('Fermer automatiquement','closeDate',localDate(draft.closeDate),'datetime-local')}${field('Nombre maximum de réponses','maxResponses',draft.maxResponses,'number','min="1" placeholder="Illimité"')}<p class="hint">${count(draft.id)} réponse(s) actuellement. Dates dans votre fuseau local.</p></div><details open><summary>Après l’envoi</summary><div id="confirmation-fields">${field('Message de confirmation · FR','confirmation',draft.confirmation,'textarea')}<div dir="rtl">${field('رسالة التأكيد · العربية','confirmationAr',draft.confirmationAr,'textarea')}</div>${toggle('Proposer une autre réponse','submitAnother',draft.submitAnother)}</div></details><div class="actions">${action('saveForm','Enregistrer','accent')}${action('preview','Aperçu')}${action('backForms','Retour aux formulaires')}</div><span id="save-indicator" class="save-indicator">${dirty?'Modifications en cours…':'Votre brouillon reste privé.'}</span><div class="danger-zone"><p class="hint">Les réponses existantes conservent la version de leurs questions, même après modification.</p></div></aside></div>`;
 bind(app.querySelector('#form-fields'),draft,changed);bind(app.querySelector('#confirmation-fields'),draft,changed);
 bind(app.querySelector('#form-settings'),draft,key=>{if(key==='closeDate')draft.closeDate=draft.closeDate?new Date(draft.closeDate).toISOString():'';changed();});
 app.querySelectorAll('[data-section]').forEach(n=>{const s=draft.sections.find(s=>s.id===n.dataset.section);bind(n.querySelector('.section-fields'),s,changed);});
 app.querySelectorAll('[data-question]').forEach(n=>{
  const q=draft.questions.find(q=>q.id===n.dataset.question);
  // Question bindings exclude nested validation controls, which belong to their own object.
  const validation=n.querySelector('.validation-fields');if(validation)validation.querySelectorAll('[data-key]').forEach(x=>x.dataset.validation='1');
  const fields=[...n.querySelectorAll('[data-key]')].filter(x=>!x.dataset.validation);
  fields.forEach(x=>x.oninput=()=>{q[x.dataset.key]=x.type==='checkbox'?x.checked:x.tagName==='SELECT'&&['max','maxBytes'].includes(x.dataset.key)?Number(x.value):x.value;changed();if(x.dataset.key==='section'){q.routes={};editor();}});
  if(validation)bind(validation,q.validation,changed);
  n.querySelector('[data-type]').onchange=event=>{q.type=event.target.value;changed();editor();};
  n.querySelectorAll('[data-option]').forEach(row=>{const [key,i]=row.dataset.option.split(':');row.querySelectorAll('[data-option-key]').forEach(input=>input.oninput=()=>{q[key][Number(i)][input.dataset.optionKey]=input.value;changed();});});
  n.querySelectorAll('[data-route]').forEach(input=>input.onchange=()=>{q.routes||={};if(input.value)q.routes[input.dataset.route]=input.value;else delete q.routes[input.dataset.route];changed();});
  n.querySelectorAll('[data-filetype]').forEach(input=>input.onchange=()=>{q.allowedTypes=[...n.querySelectorAll('[data-filetype]:checked')].map(x=>x.dataset.filetype);changed();});
  n.querySelectorAll('[data-qaction]').forEach(button=>button.onclick=()=>{
   const index=draft.questions.indexOf(q),action=button.dataset.qaction;
   if(action==='addOption'){const key=button.dataset.list;q[key].push({id:uid(),label:'',labelAr:''});}
   if(action==='removeOption'){const key=button.dataset.list;const [removed]=q[key].splice(Number(button.dataset.index),1);if(q.routes)delete q.routes[removed.id];}
   if(action==='delete'){if(!confirm('Supprimer cette question ?'))return;draft.questions.splice(index,1);}
   if(action==='duplicate'){const copy=structuredClone(q);copy.id=uid();draft.questions.splice(index+1,0,copy);}
   if(action==='up'||action==='down'){const same=draft.questions.filter(x=>x.section===q.section),i=same.indexOf(q),target=same[i+(action==='up'?-1:1)];if(target){const j=draft.questions.indexOf(target);[draft.questions[index],draft.questions[j]]=[draft.questions[j],draft.questions[index]];}}
   changed();editor();
  });
 });
 app.querySelectorAll('[data-add-question]').forEach(b=>b.onclick=()=>{draft.questions.push(newQuestion(b.dataset.addQuestion));changed();editor();app.querySelector('[data-question="'+draft.questions.at(-1).id+'"]').scrollIntoView({block:'center'});});
 app.querySelector('#add-section').onclick=()=>{draft.sections.push({id:uid(),title:'',titleAr:'',description:'',descriptionAr:''});changed();editor();};
 app.querySelectorAll('[data-section-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Supprimer cette section et ses questions ?'))return;const id=b.dataset.sectionDelete;draft.sections=draft.sections.filter(s=>s.id!==id);draft.questions=draft.questions.filter(q=>q.section!==id);for(const q of draft.questions)for(const key of Object.keys(q.routes||{}))if(q.routes[key]===id)delete q.routes[key];changed();editor();});
 wireActions();
}
async function preview(){await waitForUploads();await flushDraft();const dialog=document.querySelector('#preview-dialog'),iframe=document.querySelector('#preview-frame');iframe.src='/preview.html?id='+encodeURIComponent(draft.id)+'&lang='+document.querySelector('#preview-language').value;dialog.showModal();}
async function saveForm(){
 try{await waitForUploads();const form=validateDefinition(migrateForm(draft),!!draft.published);await flushDraft();const next=structuredClone(site),i=next.forms.findIndex(f=>f.id===form.id);if(i<0)next.forms.push(form);else next.forms[i]=form;await saveSite(next);await api('drafts/'+form.id,'DELETE');drafts=drafts.filter(d=>d.id!==form.id);notice(form.published?'Formulaire publié sur le site.':'Brouillon enregistré.');await refresh();dirty=false;draft=null;forms();}catch(err){notice(err.message,true);}
}
async function dispatch(name,id){try{
 if(name==='newForm'){if(canLeave())await startForm();}
 if(name==='editForm'){if(canLeave())await startForm(id);}
 if(name==='preview')await preview();
 if(name==='saveForm')await saveForm();
 if(name==='backForms'){await flushDraft();dirty=false;draft=null;forms();}
 if(name==='responses'){if(!canLeave())return;page='forms';dirty=false;draft=null;responses(id);}
 if(name==='newContent'){if(!canLeave())return;page=id||page;contentEditor(-1);}
 if(name==='duplicateForm'){const f=migrateForm(drafts.find(d=>d.id===id)?.value||site.forms.find(f=>f.id===id));f.id=uid();f.title=(f.title||'Formulaire')+' — copie';f.published=false;await api('drafts/'+f.id,'PUT',f);await refresh();await startForm(f.id);notice('Copie créée en brouillon.');}
 if(name==='deleteForm'){if(!confirm('Supprimer le formulaire ? Ses réponses et leurs questions restent consultables dans les archives.'))return;const next=structuredClone(site);next.forms=next.forms.filter(f=>f.id!==id);await saveSite(next);await api('drafts/'+id,'DELETE');await refresh();forms();}
 }catch(err){notice(err.message,true);}}

// Responses retain their question snapshots, including removed and renamed questions.
function responseGroups(rows){const groups=new Map();for(const r of rows)for(const q of r.snapshot.questions||[]){if(!(q.id in r.value))continue;const signature=JSON.stringify([q.id,q.label,q.labelAr,q.type,q.options,q.rows,q.columns]);if(!groups.has(signature))groups.set(signature,{q,values:[],signature});groups.get(signature).values.push(r.value[q.id]);}return [...groups.values()];}
function answerHTML(q,value){const text=e(displayAnswer(q,value));return q.type==='file'&&value?.fileId&&/^[a-f0-9]{32}\.(png|jpg|webp|pdf|txt)$/.test(value.fileId)?`<a class="text-link" href="/api/files/${value.fileId}">${icon('download')}${text}</a>`:text;}
function barChart(entries,total){if(!entries.length)return '<p class="hint">Aucune réponse à résumer.</p>';const max=Math.max(1,...entries.map(x=>x[1]));return `<svg viewBox="0 0 600 ${entries.length*57+5}" class="answer-chart" role="img" aria-label="${e(entries.map(([label,n])=>label+': '+n+' sur '+total).join(', '))}">${entries.map(([label,n],i)=>`<text x="0" y="${i*57+15}">${e(label.length>58?label.slice(0,55)+'…':label)}</text><rect x="0" y="${i*57+25}" width="${n/max*440}" height="13" rx="2"/><text x="${n/max*440+9}" y="${i*57+36}">${n} · ${Math.round(n/Math.max(1,total)*100)}%</text>`).join('')}</svg>`;}
function summaryQuestion({q,values}){
 let body='';if(['choice','dropdown','checkboxes','scale'].includes(q.type)){
  const counts=new Map();if(q.type==='scale')for(let n=q.min;n<=q.max;n++)counts.set(String(n),0);else for(const o of q.options)counts.set(o.label,0);
  for(const v of values)for(const answer of Array.isArray(v)?v:[v]){const label=displayAnswer({...q,type:q.type==='checkboxes'?'choice':q.type},answer);counts.set(label,(counts.get(label)||0)+1);}body=barChart([...counts],values.length);
 }else if(['grid','checkboxGrid'].includes(q.type))body=q.rows.map(row=>{const counts=q.columns.map(c=>[c.label,values.filter(v=>Array.isArray(v?.[row.id])?v[row.id].includes(c.id):v?.[row.id]===c.id).length]);return `<h3 style="font-size:12px;margin-block:18px">${e(row.label)}</h3>${barChart(counts,values.length)}`;}).join('');
 else body=`<ul class="summary-list">${values.map(v=>`<li>${answerHTML(q,v)}</li>`).join('')}</ul>`;
 return `<section class="panel"><h2>${e(q.label)}</h2><p class="hint">${TYPES[q.type]} · ${values.length} réponse(s) · version conservée</p>${body}</section>`;
}
function responses(id,tab='summary',index=0){
 const rows=stats.responses.filter(r=>r.form===id),form=site.forms.find(f=>f.id===id)||rows[0]?.snapshot||{title:'Formulaire archivé'};
 const groups=responseGroups(rows);
 app.innerHTML=heading('Réponses · '+(form.title||'Sans titre'),rows.length+' réponse(s). Les intitulés restent ceux du moment de l’envoi.',`<button class="button secondary" id="csv">${icon('download')}Exporter CSV</button><button class="button secondary" id="back">Retour</button>`)+`<div class="tabs" role="tablist" aria-label="Affichage des réponses">${[['summary','Résumé'],['individual','Individuelles'],['table','Tableau'],['archives','Archives']].map(([key,label])=>`<button class="tab ${tab===key?'active':''}" role="tab" aria-selected="${tab===key}" data-tab="${key}">${label}</button>`).join('')}</div><div id="response-content"></div>`;
 const content=app.querySelector('#response-content');
 if(tab==='summary')content.innerHTML=groups.map(summaryQuestion).join('')||emptyState('Les premières réponses arrivent bientôt.','Partagez le formulaire publié pour commencer.','form');
 if(tab==='individual'){
  const r=rows[Math.min(index,rows.length-1)];content.innerHTML=r?`<div class="response-nav"><button class="icon-button" id="prev-response" aria-label="Réponse précédente" ${index===0?'disabled':''}>${icon('up')}</button><span>${index+1} / ${rows.length} · ${e(new Date(r.created).toLocaleString('fr-FR'))}</span><button class="icon-button" id="next-response" aria-label="Réponse suivante" ${index>=rows.length-1?'disabled':''}>${icon('down')}</button></div><section class="panel">${(r.snapshot.questions||[]).filter(q=>q.id in r.value).map(q=>`<div class="answer-detail"><h3>${e(q.label)}</h3><p>${answerHTML(q,r.value[q.id])}</p></div>`).join('')}<button class="button danger" data-delete-response="${r.id}">${icon('trash')}Supprimer cette réponse</button></section>`:emptyState('Aucune réponse pour le moment.','Elles seront affichées ici.','form');
  const prev=app.querySelector('#prev-response'),next=app.querySelector('#next-response');if(prev)prev.onclick=()=>responses(id,tab,index-1);if(next)next.onclick=()=>responses(id,tab,index+1);
 }
 if(tab==='table'){
  content.innerHTML=`<div class="panel"><div class="toolbar"><label class="search-box">${icon('search')}<input id="response-search" aria-label="Rechercher dans les réponses" placeholder="Rechercher une réponse…"></label><select id="response-sort" aria-label="Trier les réponses"><option value="desc">Plus récentes</option><option value="asc">Plus anciennes</option></select></div><div id="response-table"></div></div>`;
  const table=()=>{const query=app.querySelector('#response-search').value.toLocaleLowerCase();let filtered=rows.filter(r=>JSON.stringify(r.value).toLocaleLowerCase().includes(query));if(app.querySelector('#response-sort').value==='asc')filtered=[...filtered].reverse();app.querySelector('#response-table').innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Réponses · version d’origine</th><th>Action</th></tr></thead><tbody>${filtered.map(r=>`<tr><td>${e(new Date(r.created).toLocaleString('fr-FR'))}</td><td>${(r.snapshot.questions||[]).filter(q=>q.id in r.value).map(q=>`<div class="answer-detail"><strong>${e(q.label)}</strong><p>${answerHTML(q,r.value[q.id])}</p></div>`).join('')}</td><td><button class="icon-button danger" data-delete-response="${r.id}" aria-label="Supprimer cette réponse">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div>${filtered.length?'':'<p class="hint">Aucune réponse correspondante.</p>'}`;bindDeletes();};app.querySelector('#response-search').oninput=table;app.querySelector('#response-sort').onchange=table;table();
 }
 if(tab==='archives'){const archived=[...new Set(stats.responses.filter(r=>!site.forms.some(f=>f.id===r.form)).map(r=>r.form))];content.innerHTML=`<div class="panel"><h2>Formulaires retirés du site</h2>${archived.map(formId=>`<div class="recent-item"><button class="text-link" data-archive="${e(formId)}">${e(stats.responses.find(r=>r.form===formId).snapshot.title||'Sans titre')}${icon('arrow')}</button></div>`).join('')||'<p class="hint">Aucun formulaire archivé avec des réponses.</p>'}</div>`;content.querySelectorAll('[data-archive]').forEach(b=>b.onclick=()=>responses(b.dataset.archive));}
 function bindDeletes(){app.querySelectorAll('[data-delete-response]').forEach(b=>b.onclick=async()=>{if(!confirm('Supprimer définitivement cette réponse et ses fichiers ?'))return;try{await api('responses/'+b.dataset.deleteResponse,'DELETE');await refresh();responses(id,tab,Math.max(0,index-1));notice('Réponse supprimée.');}catch(err){notice(err.message,true);}});}
 bindDeletes();app.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>responses(id,b.dataset.tab));app.querySelector('#back').onclick=forms;app.querySelector('#csv').onclick=()=>exportCSV(rows,groups);
}
function exportCSV(rows,groups){
 const cell=value=>'"'+String(value??'').replace(/^(\s*)([=+@-])/u,"$1'$2").replace(/"/g,'""')+'"';
 const columns=groups.map(g=>g.signature);
 const csv=[['Date',...groups.map(g=>g.q.label)],...rows.map(r=>[r.created,...columns.map(signature=>{const q=(r.snapshot.questions||[]).find(q=>JSON.stringify([q.id,q.label,q.labelAr,q.type,q.options,q.rows,q.columns])===signature);return q?displayAnswer(q,r.value[q.id]):'';})])].map(row=>row.map(cell).join(',')).join('\r\n');
 const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='infinity-space-reponses.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

function content(){
 const members=page==='members';app.innerHTML=heading(members?'Le bureau, visage par visage.':'Le journal du club.',members?'Faites glisser les membres pour changer leur ordre. Renseignez les noms et postes arabes : le site arabe n’affiche plus les champs latins.':'Une nouvelle activité ? Un moment à raconter ?',action('newContent',members?'Ajouter un membre':'Créer une annonce','accent')+(members?'<button class="button secondary" id="team-settings">Photo de groupe et présentation</button>':''))+`<div class="toolbar"><label class="search-box">${icon('search')}<input id="content-search" aria-label="Rechercher" placeholder="Rechercher…"></label><select id="content-sort" aria-label="Trier"><option value="order">${members?'Ordre d’affichage':'Date récente'}</option><option value="name">Titre / nom A–Z</option></select></div><div id="content-list"></div>${members?'':`<div class="panel"><p class="hint">Les annonces sont présentées par date décroissante sur le site.</p></div>`}`;
 const list=()=>{const query=app.querySelector('#content-search').value.toLocaleLowerCase();let items=site[page].map((o,i)=>({o,i})).filter(({o})=>(members?memberName(o):o.title).toLocaleLowerCase().includes(query));if(app.querySelector('#content-sort').value==='name')items.sort((a,b)=>(members?memberName(a.o):a.o.title).localeCompare(members?memberName(b.o):b.o.title,'fr'));else if(!members)items.sort((a,b)=>(b.o.date||'').localeCompare(a.o.date||''));else items.sort((a,b)=>Number(b.o.isPresident)-Number(a.o.isPresident)||a.o.displayOrder-b.o.displayOrder);
 app.querySelector('#content-list').innerHTML=items.length?`<div class="member-list">${items.map(({o,i})=>`<article class="member-row" ${members?'draggable="true"':''} data-content="${i}">${icon(members?'grip':'calendar')}${safeImage(o.image)?`<img src="${e(o.image)}" alt="${e(members?memberName(o):o.title)}">`:`<div class="member-placeholder">${icon(members?'people':'image')}</div>`}<div><h3>${e(members?memberName(o):o.title)}</h3><p>${e(members?o.role:o.date)}</p></div><div class="actions">${members?`<button class="icon-button" data-move="${i}:-1" aria-label="Monter le membre">${icon('up')}</button><button class="icon-button" data-move="${i}:1" aria-label="Descendre le membre">${icon('down')}</button>`:''}<button class="icon-button" data-content-edit="${i}" aria-label="Modifier">${icon('edit')}</button><button class="icon-button danger" data-content-delete="${i}" aria-label="Supprimer">${icon('trash')}</button></div></article>`).join('')}</div>`:emptyState(members?'Le collectif attend ses visages.':'Votre prochaine histoire commence ici.',members?'Ajoutez les membres du bureau et leur rôle.':'Publiez une première annonce, en français et en arabe.',members?'people':'calendar');
 app.querySelectorAll('[data-content-edit]').forEach(b=>b.onclick=()=>contentEditor(Number(b.dataset.contentEdit)));
 app.querySelectorAll('[data-content-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Supprimer cet élément du site ?'))return;try{const next=structuredClone(site);next[page].splice(Number(b.dataset.contentDelete),1);await saveSite(next);content();notice('Élément supprimé.');}catch(err){notice(err.message,true);}});
 app.querySelectorAll('[data-move]').forEach(b=>b.onclick=async()=>{const [i,delta]=b.dataset.move.split(':').map(Number);await moveMember(i,i+delta);});
 let dragged;app.querySelectorAll('[data-content]').forEach(n=>{n.ondragstart=()=>{dragged=Number(n.dataset.content);n.classList.add('dragging');};n.ondragend=()=>n.classList.remove('dragging');n.ondragover=ev=>ev.preventDefault();n.ondrop=async ev=>{ev.preventDefault();if(members&&Number.isInteger(dragged))await moveMember(dragged,Number(n.dataset.content));};});
 };app.querySelector('#content-search').oninput=list;app.querySelector('#content-sort').onchange=list;list();wireActions();const teamButton=app.querySelector('#team-settings');if(teamButton)teamButton.onclick=teamSettings;
}
async function moveMember(from,to){if(to<0||to>=site.members.length||to===from)return;try{const next=structuredClone(site);const [m]=next.members.splice(from,1);next.members.splice(to,0,m);next.members.forEach((member,i)=>member.displayOrder=i);await saveSite(next);content();notice('Ordre du bureau enregistré.');}catch(err){notice(err.message,true);}}
function contentEditor(index){
 const key=page,members=key==='members',o=index<0?{firstName:'',lastName:'',displayOrder:site.members.length,groupOrder:0,isPresident:false}:structuredClone(site[key][index]);dirty=false;
 app.innerHTML=heading(members?'Un visage du collectif.':'Une nouvelle page du journal.','Les textes français et arabes sont affichés selon la langue du visiteur.')+`<div class="${members?'member-editor-layout':''}"><div class="panel" id="content-fields">${members?`<div class="two-columns">${field('Prénom','firstName',o.firstName)}${field('Nom de famille','lastName',o.lastName)}</div><div class="two-columns" dir="rtl">${field('الاسم الشخصي · العربية','firstNameAr',o.firstNameAr)}${field('الاسم العائلي · العربية','lastNameAr',o.lastNameAr)}</div>${field('Année du mandat','year',o.year||site.team?.year||String(new Date().getFullYear()))}${bilingual('Poste · Français','المنصب · العربية',o,'role')}${toggle('Président(e) du club · un seul membre','isPresident',o.isPresident)}${bilingual('Département / groupe · Français','القسم / المجموعة · العربية',o,'group')}<div class="two-columns">${field('Ordre du groupe','groupOrder',o.groupOrder,'number')}${field('Ordre du membre','displayOrder',o.displayOrder,'number')}</div>${bilingual('Rôle et responsabilités · Français','الدور والمسؤوليات · العربية',o,'mission','textarea')}${bilingual('Biographie courte · Français','نبذة قصيرة · العربية',o,'bio','textarea')}${bilingual('Citation · Français (facultative)','اقتباس · العربية (اختياري)',o,'quote','textarea')}${selectField('Fond du portrait','tone',o.tone||'bleuVert',[['bleuVert','Bleu-vert'],['doré','Doré'],['grisBleu','Gris-bleu'],['beigeFoncé','Beige foncé']])}${field('E-mail (facultatif)','email',o.email,'email')}${field('Lien Instagram · https://','instagram',o.instagram,'url')}${field('Lien LinkedIn · https://','linkedin',o.linkedin,'url')}<div class="upload-box"><span>Portrait du membre</span><p class="hint">PNG / JPEG / WebP · 12 Mo avant compression. Les découpes transparentes sont conservées.</p><input type="file" id="portrait-file" accept="image/png,image/jpeg,image/webp" aria-label="Portrait du membre"><div id="portrait-upload-preview">${safeImage(o.image)?`<img class="upload-preview" src="${e(o.image)}" alt="Portrait actuel">`:''}</div><div class="actions"><button class="button secondary" id="recrop" type="button">Recadrer la photo actuelle</button><button class="button secondary" id="remove-photo" type="button">Retirer</button></div></div>`:bilingual('Titre · Français','العنوان · العربية',o,'title')+bilingual('Texte · Français','النص · العربية',o,'description','textarea')+field('Date de publication','date',o.date,'date')+upload('Affiche de l’annonce · format A4','image',o.image,'a4')}<div class="actions footer-actions"><button class="button accent" id="content-save">${icon('check')}Enregistrer sur le site</button><button class="button secondary" id="content-back">Annuler</button></div></div>${members?'<div class="panel member-live-panel"><h2>La carte, en direct.</h2><p class="hint">Le texte, la citation, les liens et la teinte appartiennent à ce membre.</p><label class="field"><span>Présentation</span><select id="member-preview-view"><option value="team">Page Notre équipe</option><option value="home">Carte d’accueil</option></select></label><div id="member-live-preview"></div><label class="field"><span>Langue de l’aperçu</span><select id="member-preview-language"><option value="fr">Français</option><option value="ar">العربية</option></select></label></div>':''}</div>`;
 const live=()=>{if(!members)return;const lang=app.querySelector('#member-preview-language').value;const n=app.querySelector('#member-live-preview');n.dir=lang==='ar'?'rtl':'ltr';n.innerHTML=app.querySelector('#member-preview-view').value==='team'?`<div class="team-profile-list">${TeamMemberCard(o,index<0?site.members.length:index,lang,site)}</div>`:memberCard(o,lang,site);};
 bind(app.querySelector('#content-fields'),o,()=>{dirty=true;live();});
 if(members){live();app.querySelector('#member-preview-language').onchange=live;app.querySelector('#member-preview-view').onchange=live;
  async function process(file){if(!file)return;try{const result=await cropPortrait(file);if(result){o.image=result;dirty=true;app.querySelector('#portrait-upload-preview').innerHTML=`<img class="upload-preview" src="${e(result)}" alt="Portrait recadré">`;live();}}catch(err){notice(err.message,true);}}
  app.querySelector('#portrait-file').onchange=ev=>process(ev.target.files[0]);
  app.querySelector('#remove-photo').onclick=()=>{o.image='';dirty=true;app.querySelector('#portrait-upload-preview').innerHTML='';live();};
  app.querySelector('#recrop').onclick=async()=>{if(!safeImage(o.image)){notice('Ajoutez d’abord une photo.',true);return;}try{if(o.image.startsWith('data:')){await process(dataURLFile(o.image,'portrait.webp'));return;}const response=await fetch(o.image);const blob=await response.blob();await process(new File([blob],'portrait.'+blob.type.split('/')[1],{type:blob.type}));}catch{notice('Réimportez la photo originale pour la recadrer.',true);}};
 }
 app.querySelector('#content-back').onclick=()=>{if(canLeave()){dirty=false;content();}};
 app.querySelector('#content-save').onclick=async()=>{if(!String(members?o.firstName:o.title||'').trim()){notice('Le prénom ou le titre est obligatoire.',true);return;}try{const next=structuredClone(site);if(members){o.id||=uid();o.name=memberName(o);if(o.isPresident){const existing=next.members.find((m,i)=>m.isPresident&&i!==index);if(existing&&!confirm(memberName(existing)+' est actuellement à la présidence. Transférer ce rôle ?'))return;next.members.forEach(m=>m.isPresident=false);}}if(index<0)next[key].push(o);else next[key][index]=o;await saveSite(next);notice('Le site est à jour.');content();}catch(err){notice(err.message,true);}};
}
function identity(){
 const model=structuredClone(site);model.footer||={};model.footer.links||=[{label:'Le collectif',labelAr:'النادي',url:'/#about'},{label:'Actualités',labelAr:'المستجدات',url:'/#events'},{label:'Participer',labelAr:'المشاركة',url:'/#forms'},{label:'Notre équipe',labelAr:'فريقنا',url:'/team'}];dirty=false;app.innerHTML=heading('La signature du collectif.','Votre logo, toujours entier. Sur fond clair comme sur fond sombre.')+`<div class="panel" id="identity-fields"><h2>Le logo du club</h2><p>Privilégiez un PNG transparent de bonne qualité. Un format carré ou horizontal fonctionne : le logo est contenu dans une tuile neutre, jamais étiré ni recadré.</p>${upload('Logo original · fond clair','logo',model.logo)}${upload('Logo pour les fonds sombres','darkLogo',model.darkLogo)}${field('Slogan · Français','slogan',model.slogan||'Infinity pation in one space')}<div dir="rtl">${field('شعار النادي · العربية','sloganAr',model.sloganAr||'شغف بلا حدود في فضاء واحد')}</div><div id="logo-previews"></div><h2>La faculté, à vos côtés</h2>${upload('Logo officiel de la Faculté des Sciences Ben M’Sik','facultyLogo',model.facultyLogo)}<p class="hint">Le logo officiel apparaît dans le pied de page, près du nom de la faculté.</p></div><div class="panel" id="temporary-fields"><h2>Une occasion, une variation.</h2><p>Le logo temporaire est utilisé jusqu’à la date choisie. L’original reprend sa place automatiquement.</p>${upload('Logo événementiel','temporaryLogo',model.temporaryLogo)}${field('Retour au logo original · heure locale','logoUntil',localDate(model.logoUntil),'datetime-local')}</div><div class="panel" id="footer-fields"><h2>Le dernier mot, à votre image.</h2><p>Ces textes et liens apparaissent dans le pied de page sur toutes les pages du site. Les liens vides restent masqués.</p>${bilingual('Description du club · Français','تعريف النادي · العربية',model.footer,'description','textarea')}${field('Instagram · lien https://','instagram',model.footer.instagram,'url')}${field('Facebook · lien https://','facebook',model.footer.facebook,'url')}${field('E-mail de contact','email',model.footer.email,'email')}${field('WhatsApp · indicatif international et chiffres','whatsapp',model.footer.whatsapp,'tel')}${bilingual('Adresse · Français','العنوان · العربية',model.footer,'address','textarea')}${field('Plan / carte · lien https://','map',model.footer.map,'url')}<h2 style="margin-block-start:25px">Liens de navigation</h2><div id="footer-navigation-editor"></div><button type="button" class="button secondary" id="footer-add-link">${icon('plus')}Ajouter un lien</button><div class="actions footer-actions"><button class="button accent" id="identity-save">${icon('check')}Enregistrer l’identité et le pied de page</button></div></div>`;
 const previews=()=>{app.querySelector('#logo-previews').innerHTML=`<div class="logo-previews"><div class="logo-header-preview"><small>En-tête · fond clair</small><span class="brand">${wordmark(model)}</span></div><div class="logo-header-preview dark"><small>En-tête · fond sombre</small><span class="brand">${wordmark(model,'fr',true)}</span></div></div>`;};
 const navigationEditor=()=>{app.querySelector('#footer-navigation-editor').innerHTML=model.footer.links.map((link,i)=>`<div class="footer-link-row" data-footer-link="${i}"><div class="two-columns"><label class="field"><span>Libellé · FR</span><input data-navkey="label" value="${e(link.label)}"></label><label class="field" dir="rtl"><span>العنوان · العربية</span><input data-navkey="labelAr" value="${e(link.labelAr)}"></label></div><label class="field"><span>Destination · /chemin ou https://</span><input data-navkey="url" value="${e(link.url)}"></label><button type="button" class="icon-button danger" data-navremove="${i}" aria-label="Supprimer ce lien">${icon('trash')}</button></div>`).join('');app.querySelectorAll('[data-footer-link]').forEach(row=>row.querySelectorAll('[data-navkey]').forEach(input=>input.oninput=()=>{model.footer.links[Number(row.dataset.footerLink)][input.dataset.navkey]=input.value;dirty=true;}));app.querySelectorAll('[data-navremove]').forEach(b=>b.onclick=()=>{model.footer.links.splice(Number(b.dataset.navremove),1);dirty=true;navigationEditor();});};navigationEditor();app.querySelector('#footer-add-link').onclick=()=>{model.footer.links.push({label:'',labelAr:'',url:''});dirty=true;navigationEditor();};
 bind(app.querySelector('#footer-fields'),model.footer);bind(app.querySelector('#identity-fields'),model,()=>{dirty=true;previews();});bind(app.querySelector('#temporary-fields'),model,key=>{if(key==='logoUntil')model.logoUntil=model.logoUntil?new Date(model.logoUntil).toISOString():'';dirty=true;previews();});previews();app.querySelector('#identity-save').onclick=async()=>{if(model.temporaryLogo&&!model.logoUntil){notice('Choisissez une date de fin pour le logo temporaire.',true);return;}try{await saveSite(model);notice('Identité enregistrée sur le site.');identity();}catch(err){notice(err.message,true);}};
}
document.querySelector('#admin-nav').innerHTML=Object.entries(labels).map(([key,[i,label]])=>`<button class="nav-button" data-page="${key}">${icon(i)}<span>${label}</span></button>`).join('');
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{if(site)navigate(b.dataset.page);});
document.querySelector('#logout').innerHTML=icon('logout')+'<span>Déconnexion</span>';
document.querySelector('#logout').onclick=async()=>{if(!canLeave())return;await api('logout','POST');dirty=false;clearTimeout(autosaveTimer);draft=null;login();};
document.querySelector('#preview-close').innerHTML=icon('close');document.querySelector('#preview-close').onclick=()=>document.querySelector('#preview-dialog').close();
document.querySelector('#preview-size').onclick=ev=>{const mobile=document.querySelector('#preview-dialog').classList.toggle('mobile');ev.target.textContent=mobile?'Vue bureau':'Vue mobile';};
document.querySelector('#preview-language').onchange=()=>{document.querySelector('#preview-frame').src='/preview.html?id='+encodeURIComponent(draft.id)+'&lang='+document.querySelector('#preview-language').value;};
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
refresh().then(render).catch(err=>{if(err.status===401)login();else{notice('Impossible de charger le contenu : '+err.message,true);login();}});

document.querySelector("#mobile-logout").innerHTML=icon("logout");document.querySelector("#mobile-logout").onclick=()=>document.querySelector("#logout").click();

function teamSettings(){
 const model=structuredClone(site.team||{});dirty=false;
 app.innerHTML=heading('Le collectif, au complet.','La photo de groupe et le texte de présentation apparaissent sur la page Équipe.')+`<div class="panel" id="team-fields">${field('Année / mandat du bureau','year',model.year||String(new Date().getFullYear()))}${upload('Grande photo de groupe','image',model.image)}${bilingual('Légende de la photo · Français','وصف الصورة الجماعية · العربية',model,'caption')}${bilingual('Notre esprit d’équipe · Français','روح الفريق · العربية',model,'intro','textarea')}${bilingual('Renouvellement du bureau et égalité · Français','تجديد المكتب والمساواة · العربية',model,'rotation','textarea')}<p class="hint">Sans texte personnalisé, le site explique la même valeur de chaque membre et la rotation des responsabilités.</p><div class="actions footer-actions"><button class="button accent" id="team-save">${icon('check')}Enregistrer</button><button class="button secondary" id="team-back">Retour au bureau</button></div></div>`;
 bind(app.querySelector('#team-fields'),model);
 app.querySelector('#team-back').onclick=()=>{if(canLeave()){dirty=false;content();}};
 app.querySelector('#team-save').onclick=async()=>{try{await waitForUploads();const next=structuredClone(site);next.team=model;await saveSite(next);notice('Présentation de l’équipe enregistrée.');content();}catch(err){notice(err.message,true);}};
}
function activityList(){
 app.innerHTML=heading('Les moments qu’on garde.','Les activités précédentes, classées par cellule.','<button class="button accent" id="new-activity">'+icon('plus')+'Créer une activité</button>')+`<div class="panel"><div class="toolbar"><label class="search-box">${icon('search')}<input id="activity-search" aria-label="Rechercher une activité" placeholder="Rechercher une activité…"></label><select id="activity-cell" aria-label="Filtrer par cellule"><option value="">Toutes les cellules</option>${CELLS.map(c=>`<option value="${c.id}">${e(c.title)}</option>`).join('')}</select></div><div id="activities-list"></div></div>`;
 function list(){const query=app.querySelector('#activity-search').value.toLocaleLowerCase(),cell=app.querySelector('#activity-cell').value;const items=(site.activities||[]).map((a,i)=>({a,i})).filter(({a})=>(!cell||a.cell===cell)&&a.title.toLocaleLowerCase().includes(query)).sort((x,y)=>(y.a.date||'').localeCompare(x.a.date||''));
  app.querySelector('#activities-list').innerHTML=items.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Activité</th><th>Cellule</th><th>Date</th><th>Photos</th><th>Actions</th></tr></thead><tbody>${items.map(({a,i})=>`<tr><td>${e(a.title)}</td><td>${e(CELLS.find(c=>c.id===a.cell)?.title)}</td><td>${e(a.date)}</td><td>${a.media?.length||0}</td><td><div class="actions"><button class="icon-button" data-edit-activity="${i}" aria-label="Modifier l’activité">${icon('edit')}</button><button class="icon-button danger" data-delete-activity="${i}" aria-label="Supprimer l’activité">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:emptyState('Une première histoire à raconter.','Choisissez une cellule, ajoutez vos photos et racontez chaque moment.','calendar');
  app.querySelectorAll('[data-edit-activity]').forEach(b=>b.onclick=()=>activityEditor(Number(b.dataset.editActivity)));
  app.querySelectorAll('[data-delete-activity]').forEach(b=>b.onclick=async()=>{if(!confirm('Retirer cette activité du site ?'))return;try{const next=structuredClone(site);next.activities.splice(Number(b.dataset.deleteActivity),1);await saveSite(next);activityList();notice('Activité retirée.');}catch(err){notice(err.message,true);}});
 }
 app.querySelector('#activity-search').oninput=list;app.querySelector('#activity-cell').onchange=list;app.querySelector('#new-activity').onclick=()=>activityEditor(-1);list();
}
function activityEditor(index){
 const model=index<0?{id:uid(),cell:'sport',date:new Date().toISOString().slice(0,10),title:'',titleAr:'',description:'',descriptionAr:'',media:[]}:structuredClone(site.activities[index]);dirty=false;
 function draw(){
  app.innerHTML=heading('Une activité, plusieurs moments.','Image à droite, texte à gauche, puis l’inverse. Chaque photo conserve sa propre description.')+`<div class="panel" id="activity-fields">${selectField('Cellule','cell',model.cell,CELLS.map(c=>[c.id,c.title]))}${field('Date de l’activité','date',model.date,'date')}${bilingual('Nom de l’activité · Français','اسم النشاط · العربية',model,'title')}${bilingual('Introduction · Français','تقديم النشاط · العربية',model,'description','textarea')}${bilingual('Mot du titre en italique · Français','الكلمة المميزة في العنوان · العربية',model,'accentWord')}<div class="two-columns"><label class="field"><span>Mots-clés à mettre en valeur · FR, séparés par une virgule</span><input data-keywords="keywords" value="${e((model.keywords||[]).join(', '))}"></label><label class="field" dir="rtl"><span>الكلمات المميزة · مفصولة بفاصلة</span><input data-keywords="keywordsAr" value="${e((model.keywordsAr||[]).join('، '))}"></label></div></div><div id="activity-media-fields">${model.media.map((m,i)=>`<section class="panel activity-media-editor" data-media-index="${i}"><div class="question-toolbar"><h2>Moment ${i+1}</h2><div class="actions"><button class="icon-button" data-media-move="${i}:-1" aria-label="Monter la photo">${icon('up')}</button><button class="icon-button" data-media-move="${i}:1" aria-label="Descendre la photo">${icon('down')}</button><button class="icon-button danger" data-media-delete="${i}" aria-label="Retirer la photo">${icon('trash')}</button></div></div>${bilingual('Titre du bloc · Français','عنوان الفقرة · العربية',m,'title')}${upload('Photo du moment '+(i+1),'image',m.image)}${bilingual('Courte description · Français','وصف قصير · العربية',m,'caption','textarea')}<p class="hint">Template commun : photo 4:3, alternance automatique et numérotation. Pour changer le contenu hors admin : data/activities/${e(model.cell)}.js.</p></section>`).join('')}</div><button class="button secondary" id="activity-add-photo">${icon('plus')}Ajouter une photo</button><div class="panel" style="margin-block-start:25px"><h2>Le rendu sur le site, en direct.</h2><label class="field"><span>Langue de l’aperçu</span><select id="activity-preview-language"><option value="fr">Français</option><option value="ar">العربية</option></select></label><div id="activity-preview"></div></div><div class="actions footer-actions"><button class="button accent" id="activity-save">${icon('check')}Publier l’activité</button><button class="button secondary" id="activity-back">Retour aux activités</button></div>`;
  const preview=()=>{const lang=app.querySelector('#activity-preview-language').value;const root=app.querySelector('#activity-preview');root.dir=lang==='ar'?'rtl':'ltr';root.innerHTML=ActivityArticle(model,lang);};
  bind(app.querySelector('#activity-fields'),model,()=>{dirty=true;preview();});
  app.querySelectorAll('[data-media-index]').forEach(n=>bind(n,model.media[Number(n.dataset.mediaIndex)],()=>{dirty=true;preview();}));
  app.querySelector('#activity-preview-language').onchange=preview;app.querySelectorAll('[data-keywords]').forEach(input=>input.oninput=()=>{model[input.dataset.keywords]=input.value.split(/[,،]/).map(x=>x.trim()).filter(Boolean);dirty=true;preview();});preview();
  app.querySelector('#activity-add-photo').onclick=()=>{model.media.push({image:'',title:'',titleAr:'',caption:'',captionAr:'',format:'landscape',width:100,height:302});dirty=true;draw();};
  app.querySelectorAll('[data-media-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Retirer cette photo de l’activité ?'))return;model.media.splice(Number(b.dataset.mediaDelete),1);dirty=true;draw();});
  app.querySelectorAll('[data-media-move]').forEach(b=>b.onclick=()=>{const [i,delta]=b.dataset.mediaMove.split(':').map(Number),j=i+delta;if(j<0||j>=model.media.length)return;[model.media[i],model.media[j]]=[model.media[j],model.media[i]];dirty=true;draw();});
  app.querySelector('#activity-back').onclick=()=>{if(canLeave()){dirty=false;activityList();}};
  app.querySelector('#activity-save').onclick=async()=>{try{await waitForUploads();if(!model.title.trim()||!model.date||!model.media.some(m=>safeImage(m.image)))throw Error('Ajoutez un titre, une date et au moins une photo.');const next=structuredClone(site);const activity={...model,media:model.media.filter(m=>safeImage(m.image))};next.activities||=[];if(index<0)next.activities.push(activity);else next.activities[index]=activity;await saveSite(next);notice('Activité publiée.');activityList();}catch(err){notice(err.message,true);}};
 }
 draw();
}
